TEST(fftpack_forward_matches_jvm) {
    for (const FftCase &c : fftCases()) {
        std::vector<double> x = makeInput(c.n);
        ComplexDoubleFFT fft(c.n);
        fft.ft(x);
        CHECK_EQ(x.size(), c.expected.size());
        for (std::size_t i = 0; i < x.size(); i++) {
            // Not exact: cffti1 tabulates the wavetable with sin and cos, and
            // one of those values differs from the JVM by an ulp (see
            // TrigProbeTest). That propagates through the butterflies into
            // every bin. Largest deviation observed across all sizes here is
            // 1.8e-15 on values up to ~13, so 1e-12 leaves headroom while
            // still catching anything structural.
            CHECK_CLOSE(x[i], c.expected[i], 1e-12);
        }
    }
}

TEST(fftpack_roundtrip_scales_by_n) {
    // bt(ft(v)) == n * v, to within the accumulated rounding the JVM also sees.
    for (const FftCase &c : fftCases()) {
        std::vector<double> orig = makeInput(c.n);
        std::vector<double> x = orig;
        ComplexDoubleFFT fwd(c.n);
        fwd.ft(x);
        ComplexDoubleFFT inv(c.n);
        inv.bt(x);
        // The rounding a round trip accumulates is set by the largest value in
        // the vector, not by the element being checked -- a bin that happens to
        // come out near zero still carries the error of its neighbours. So the
        // bound is scaled by the largest expected magnitude in this case.
        double scale = 1.0;
        for (std::size_t i = 0; i < x.size(); i++)
            scale = std::max(scale, std::abs(c.n * orig[i]));

        for (std::size_t i = 0; i < x.size(); i++) {
            CHECK(std::abs(x[i] - c.n * orig[i]) <= 1e-12 * scale);
        }
    }
}

TEST(fftpack_norm_factor_and_size_check) {
    ComplexDoubleFFT fft(16);
    CHECK_CLOSE(fft.norm_factor, 16.0, 0.0);

    std::vector<double> wrong(10, 0.0);
    CHECK_THROWS(fft.ft(wrong), IllegalArgumentException);
    CHECK_THROWS(fft.bt(wrong), IllegalArgumentException);

    Complex1D c;
    c.x.assign(10, 0.0);
    c.y.assign(10, 0.0);
    CHECK_THROWS(fft.ft(c), IllegalArgumentException);
}

TEST(fftpack_complex1d_matches_interleaved) {
    const int n = 12;
    std::vector<double> flat = makeInput(n);
    Complex1D c;
    c.x.resize(n);
    c.y.resize(n);
    for (int i = 0; i < n; i++) {
        c.x[i] = flat[2 * i];
        c.y[i] = flat[2 * i + 1];
    }
    ComplexDoubleFFT(n).ft(flat);
    ComplexDoubleFFT(n).ft(c);
    for (int i = 0; i < n; i++) {
        CHECK_CLOSE(c.x[i], flat[2 * i], 0.0);
        CHECK_CLOSE(c.y[i], flat[2 * i + 1], 0.0);
    }
}
